class Encoder:
    def __init__(self, shift):
        self.shift = shift
    def encode(self, text):
        result = ''
        for ch in text:
            if ch.isalpha():
                result += chr(ord(ch) + self.shift)
            else:
                result += ch
        return result
    def decode(self, text):
        result = ''
        for ch in text:
            if ch.isalpha():
                result += chr(ord(ch) - self.shift)
            else:
                result += ch
        return result

