                f.write(','.join(str(v) for v in row))

import os
with open('input.csv', 'w', encoding='utf-8') as _f:
    _f.write(os.linesep.join(['1,Alice,150', '2,Bob,200', '3,Charlie,50'] + ['']))

def extract_raw_data(filepath):
    with open(filepath) as f:
        lines = f.readlines()
    records = []
    for line in lines:
        parts = line.strip().split(',')
        if len(parts) >= 3:
            records.append({
                'id': int(parts[0]),
                'name': parts[1],
                'value': float(parts[2]),
            })
    return records

def transform_data(records):
    result = []
    for r in records:
        transformed = {
            'id': r['id'],
            'name': r['name'].strip().title(),
            'value': round(r['value'] * 1.1, 2),
            'category': 'A' if r['value'] > 100 else 'B',
        }
        result.append(transformed)
    return result

def validate_data(records):
    valid = []
    errors = []
    for i, r in enumerate(records):
        if r['id'] <= 0:
            errors.append(f'Row {i}: invalid id {r["id"]}')
            continue
        if not r['name']:
            errors.append(f'Row {i}: empty name')
            continue
        if r['value'] < 0:
            errors.append(f'Row {i}: negative value')
            continue
        valid.append(r)
    return valid, errors

def load_data(records, output_path):
    with open(output_path, 'w') as f:
        f.write('id,name,value,category')
        for r in records:
            f.write(f"{r['id']},{r['name']},{r['value']},{r['category']}")
    return len(records)

def run_pipeline(input_path, output_path):
    raw = extract_raw_data(input_path)
    print(f'Extracted: {len(raw)} records')
    transformed = transform_data(raw)
    print(f'Transformed: {len(transformed)} records')
    valid, errors = validate_data(transformed)
    if errors:
        print(f'Validation errors: {len(errors)}')
        for e in errors:
            print(f'  {e}')
    count = load_data(valid, output_path)
    print(f'Loaded: {count} records to {output_path}')
    return count

result = run_pipeline('input.csv', 'output.csv')

