import math

class DataAnalyzer:
    def __init__(self, data):
        self.data = data
        self.n = len(data)

    def mean(self):
        if self.n == 0:
            return 0
        return sum(self.data) / self.n

    def median(self):
        sorted_data = sorted(self.data)
        mid = self.n // 2
        if self.n % 2 == 0:
            return (sorted_data[mid - 1] + sorted_data[mid]) / 2
        else:
            return sorted_data[mid]

    def variance(self):
        if self.n <= 1:
            return 0
        m = self.mean()
        squared_diffs = [(x - m) ** 2 for x in self.data]
        return sum(squared_diffs) / (self.n - 1)

    def std_dev(self):
        return math.sqrt(self.variance())

    def summary(self):
        return {
            'count': self.n,
            'mean': round(self.mean(), 2),
            'median': round(self.median(), 2),
            'std_dev': round(self.std_dev(), 2),
            'min': min(self.data) if self.data else None,
            'max': max(self.data) if self.data else None,
        }

    def filter_outliers(self, threshold=2):
        m = self.mean()
        s = self.std_dev()
        lower = m - threshold * s
        upper = m + threshold * s
        return [x for x in self.data if lower <= x <= upper]

