import heapq

class TaskScheduler:
    def __init__(self):
        self.tasks = []
        self.completed = []
        self.counter = 0

    def add_task(self, name, priority, duration):
        if priority < 0 or duration <= 0:
            raise ValueError("Invalid priority or duration")
        self.counter += 1
        entry = (priority, self.counter, name, duration, 'pending')
        heapq.heappush(self.tasks, entry)
        return self.counter

    def get_next_task(self):
        if not self.tasks:
            return None
        priority, _, name, duration, status = heapq.heappop(self.tasks)
        return {'name': name, 'priority': priority, 'duration': duration}

    def complete_task(self, name):
        self.completed.append(name)
        return len(self.completed)

    def pending_count(self):
        return len(self.tasks)

    def get_high_priority_tasks(self, max_priority=3):
        return [t for t in self.tasks if t[0] <= max_priority]

    def estimate_total_time(self):
        return sum(t[3] for t in self.tasks) if self.tasks else 0

    def report(self):
        return {
            'pending': self.pending_count(),
            'completed': len(self.completed),
            'total_estimated': self.estimate_total_time(),
            'high_priority_pending': len(self.get_high_priority_tasks())
        }

