import re
from collections import Counter

class TextProcessor:
    def __init__(self, text):
        self.text = text
        self._words = None
        self._sentences = None

    def clean(self):
        cleaned = re.sub(r'[^\w\s]', '', self.text.lower())
        return cleaned

    def tokenize(self):
        if self._words is None:
            self._words = self.clean().split()
        return self._words

    def sentences(self):
        if self._sentences is None:
            raw = re.split(r'[.!?]+', self.text)
            self._sentences = [s.strip() for s in raw if s.strip()]
        return self._sentences

    def word_count(self):
        return len(self.tokenize())

    def sentence_count(self):
        return len(self.sentences())

    def word_frequency(self):
        words = self.tokenize()
        counter = Counter(words)
        return dict(counter.most_common(10))

    def unique_words(self):
        return len(set(self.tokenize()))

    def average_word_length(self):
        words = self.tokenize()
        if not words:
            return 0
        return sum(len(w) for w in words) / len(words)

    def longest_word(self):
        words = self.tokenize()
        if not words:
            return None
        return max(words, key=len)

    def search(self, keyword):
        keyword = keyword.lower()
        words = self.tokenize()
        indices = [i for i, w in enumerate(words) if w == keyword]
        return indices

    def summary(self):
        return {
            'chars': len(self.text),
            'words': self.word_count(),
            'sentences': self.sentence_count(),
            'unique_words': self.unique_words(),
            'top_words': self.word_frequency(),
        }

