print(f"Top words: {tp.word_frequency()}")
print(f"Longest word: {tp.longest_word()}")
indices = tp.search("python")
print(f"'python' found at positions: {indices}")

from collections import deque, defaultdict

class Graph:
    def __init__(self):
        self.adj = defaultdict(list)

    def add_edge(self, u, v, weight=1):
        self.adj[u].append((v, weight))
        if v not in self.adj:
            self.adj[v] = []

    def bfs(self, start):
        visited = set()
        queue = deque([start])
        order = []
        while queue:
            node = queue.popleft()
            if node not in visited:
                visited.add(node)
                order.append(node)
                for neighbor, _ in self.adj[node]:
                    if neighbor not in visited:
                        queue.append(neighbor)
        return order

    def dfs(self, start):
        visited = set()
        order = []
        stack = [start]
        while stack:
            node = stack.pop()
            if node not in visited:
                visited.add(node)
                order.append(node)
                for neighbor, _ in reversed(self.adj[node]):
                    if neighbor not in visited:
                        stack.append(neighbor)
        return order

    def has_path(self, start, end):
        visited = set()
        queue = deque([start])
        while queue:
            node = queue.popleft()
            if node == end:
                return True
            if node not in visited:
                visited.add(node)
                for neighbor, _ in self.adj[node]:
                    if neighbor not in visited:
                        queue.append(neighbor)
        return False

    def shortest_path(self, start, end):
        if start == end:
            return [start], 0
        visited = set()
        queue = deque([(start, [start], 0)])
        while queue:
            node, path, dist = queue.popleft()
            if node == end:
                return path, dist
            if node not in visited:
                visited.add(node)
                for neighbor, weight in self.adj[node]:
                    if neighbor not in visited:
                        new_path = path + [neighbor]
                        new_dist = dist + weight
                        queue.append((neighbor, new_path, new_dist))
        return None, -1

